                                                                                                                                                                                                                                                                                                                                                                                                                                                       
  CREATE OR REPLACE FORCE EDITIONABLE VIEW "TENANT_EVENT_AUDIT_V" ("EVENT_ID", "SUBMIT_USER_ID", "SUBMIT_EXT_ORG_ID", "SUBMIT_SOURCE", "DESCRIPTION", "AFFECTED_RANGE", "TENANT_ID", "REMARK", "FAB_ID", "MAP_AREA_X_ID", "MAP_AREA_Y_ID", "FAB_NAME", "MAP_AREA_X_NAME", "MAP_AREA_Y_NAME", "FIRST_EVENT_CODE", "SECOND_EVENT_CODE", "PHENOMENON_CODE", "FIRST_EVENT_NAME", "SECOND_EVENT_NAME", "PHENOMENON_NAME", "BASE_DEPT_ID") AS     
  select EVENT_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                     
       SUBMIT_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                 
       SUBMIT_EXT_ORG_ID,                                                                                                                                                                                                                                                                                                                                                                                                                              
       SUBMIT_SOURCE,                                                                                                                                                                                                                                                                                                                                                                                                                                  
       DESCRIPTION,                                                                                                                                                                                                                                                                                                                                                                                                                                    
       AFFECTED_RANGE,                                                                                                                                                                                                                                                                                                                                                                                                                                 
       e.TENANT_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                    
       e.REMARK,                                                                                                                                                                                                                                                                                                                                                                                                                                       
       e.FAB_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                       
       e.MAP_AREA_X_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                
       e.MAP_AREA_Y_ID,                                                                                                                                                                                                                                                                                                                                                                                                                                
       FAB_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                       
       MAP_AREA_X_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                
       MAP_AREA_Y_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                                
       FIRST_EVENT_CODE,                                                                                                                                                                                                                                                                                                                                                                                                                               
       SECOND_EVENT_CODE,                                                                                                                                                                                                                                                                                                                                                                                                                              
       PHENOMENON_CODE,                                                                                                                                                                                                                                                                                                                                                                                                                                
       ec1.NAME as FIRST_EVENT_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                   
       ec2.NAME as SECOND_EVENT_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                  
       ep.NAME  as PHENOMENON_NAME,                                                                                                                                                                                                                                                                                                                                                                                                                    
       e.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                                                                  
from TENANT_EVENT e                                                                                                                                                                                                                                                                                                                                                                                                                                    
         left join FND_MAPS_AREAS_ASSO_V map on e.MAP_ID = map.MAP_ID and e.BASE_DEPT_ID = map.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                            
         left join TENANT_EVENT_CATEGORY ec1 on e.FIRST_EVENT_CODE = ec1.CODE and e.BASE_DEPT_ID = ec1.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                    
         left join TENANT_EVENT_CATEGORY ec2 on e.SECOND_EVENT_CODE = ec2.CODE and e.BASE_DEPT_ID = ec2.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                   
         left join TENANT_EVENT_PHENOMENON ep on e.PHENOMENON_CODE = ep.CODE and e.BASE_DEPT_ID = ep.BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                      
where e.DEL_FLAG = 0                                                                                                                                                                                                                                                                                                                                                                                                                                   
  and e.STATUS = 'CLOSED';                                                                                                                                                                                                                                                                                                                                                                                                                             

